-- 1. MAXIMUS — [M1 | automate_dv.ma_sat] SAT_PARTY_CONTACT_ADDRESS_LINK   [Implemented]
-- Same comparison as DM-A2 (latest satellite row vs the latest RAW record, model logic
-- recomputed from RAW) but the sample is the most recently loaded keys, i.e. the keys
-- that just changed -- where a stale current row would show. standard satellite,
-- automate_dv.ma_sat; PK PARTY_LOCATION_HKEY, child key ADDRESS_USAGE_TYPE; 1
-- RECORD_SOURCE group(s):
-- MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
-- [2 col(s)]. Multi-active: compared per (key, child key); latest = max LOAD_DATETIME
-- per member.
----------------------------------------------------------------------------------------
with s1 as (  -- the 100 most recently loaded keys of this RECORD_SOURCE (latest changes)
    select PARTY_LOCATION_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_CONTACT_ADDRESS_LINK
     where RECORD_SOURCE = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW'
     group by PARTY_LOCATION_HKEY
     order by max(LOAD_DATETIME) desc, hkey
     limit 100
),
c1 as (  -- latest satellite row per sampled key
    select PARTY_LOCATION_HKEY as hkey,
           to_varchar(ADDRESS_USAGE_TYPE) as cdk_1,
           to_varchar(ADDRESSUSAGETYPE) as ADDRESSUSAGETYPE,
           to_varchar(PRIMARYADDRESSINDICATOR) as PRIMARYADDRESSINDICATOR
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_CONTACT_ADDRESS_LINK
     where RECORD_SOURCE = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW'
       and PARTY_LOCATION_HKEY in (select hkey from s1)
    qualify rank() over (partition by PARTY_LOCATION_HKEY, ADDRESS_USAGE_TYPE order by LOAD_DATETIME desc) = 1
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via unpivot_mp__pd_prop_sp_pv__party_contact_address_link#1
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('LNK_PARTY_LOCATION|' || (((nullif(trim(to_varchar("FOREIGN_KEY")), '')))) AS VARCHAR))), '')) as hkey,
               to_varchar('COMMUNICATION') as cdk_1,
               (("REC_REFRESH_AT"::timestamp_ntz)) as ldts,
               cast(null as varchar) as ADDRESSUSAGETYPE,
               to_varchar((nullif(trim(to_varchar("IS_THE_MAILINGCOMMUNICATION_ADDRESS_SAME_AS_THE_PRIMARY_ADDRESS")), ''))) as PRIMARYADDRESSINDICATOR
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
         where nullif(trim(to_varchar((nullif(trim(to_varchar("IS_THE_MAILINGCOMMUNICATION_ADDRESS_SAME_AS_THE_PRIMARY_ADDRESS")), '')))), '') is not null
        union all
        -- via unpivot_mp__pd_prop_sp_pv__party_contact_address_link#2
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('LNK_PARTY_LOCATION|' || (((nullif(trim(to_varchar("FOREIGN_KEY")), '')))) AS VARCHAR))), '')) as hkey,
               to_varchar('{CURRENT_PERMANENT_OVERSEAS_ADDRESS_TYPE}') as cdk_1,
               (("REC_REFRESH_AT"::timestamp_ntz)) as ldts,
               to_varchar((nullif(trim(to_varchar("CURRENT_PERMANENT_OVERSEAS_ADDRESS_TYPE")), ''))) as ADDRESSUSAGETYPE,
               cast(null as varchar) as PRIMARYADDRESSINDICATOR
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
         where nullif(trim(to_varchar((nullif(trim(to_varchar("CURRENT_PERMANENT_OVERSEAS_ADDRESS_TYPE")), '')))), '') is not null
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey, cdk_1 order by ldts desc) = 1
),
r1 as (
    select 'ADDRESSUSAGETYPE' as column_name, c.hkey, c.ADDRESSUSAGETYPE as sat_value,
           max(iff(equal_null(c.ADDRESSUSAGETYPE, e.ADDRESSUSAGETYPE), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.ADDRESSUSAGETYPE) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey and equal_null(e.cdk_1, c.cdk_1)
     group by c.hkey, c.cdk_1, c.ADDRESSUSAGETYPE
    union all
    select 'PRIMARYADDRESSINDICATOR' as column_name, c.hkey, c.PRIMARYADDRESSINDICATOR as sat_value,
           max(iff(equal_null(c.PRIMARYADDRESSINDICATOR, e.PRIMARYADDRESSINDICATOR), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.PRIMARYADDRESSINDICATOR) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey and equal_null(e.cdk_1, c.cdk_1)
     group by c.hkey, c.cdk_1, c.PRIMARYADDRESSINDICATOR
)
select 'MAXIMUS' as project, 'SAT_PARTY_CONTACT_ADDRESS_LINK' as satellite, 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW' as record_source, column_name,
       count(*) as keys_compared,
       count_if(src_rows > 0 and matched = 1) as matched,
       count_if(src_rows > 0 and matched = 0) as mismatched,
       count_if(src_rows = 0) as no_source_row,
       array_slice(array_agg(iff(src_rows > 0 and matched = 0, object_construct('hkey', to_varchar(hkey, 'HEX'), 'sat', sat_value, 'src', src_value), null))
                   within group (order by hkey), 0, 3) as mismatch_examples,
       iff(mismatched = 0 and no_source_row = 0, 'PASS', 'FAIL') as status
  from r1
 group by column_name
order by record_source, column_name;



