-- 12. MAXIMUS — [M1 | sat_multi_source(OBJECT)] SAT_PARTY_IDENTIFICATION   [Implemented]
-- Same comparison as DM-A2 (latest satellite row vs the latest RAW record, model logic
-- recomputed from RAW) but the sample is the most recently loaded keys, i.e. the keys
-- that just changed -- where a stale current row would show. standard satellite,
-- sat_multi_source; PK PARTY_HKEY; 2 RECORD_SOURCE group(s):
-- MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW
-- [3 col(s)],
-- MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
-- [27 col(s)]. OBJECT satellite: AADHAARNUMBER, GSTIN, PANNUMBER, PASSPORTNUMBER,
-- VOTERIDNUMBER, CKYCNUMBER hold one entry per source table (sat value = col:"<TABLE>";
-- expected = MAX over that table's RAW rows, as the macro does). Plain columns are MAX
-- across all tables and are not compared per table. A table absent from the latest
-- incremental window is absent from the latest row -- compare after a full load.
----------------------------------------------------------------------------------------
with s1 as (  -- the 100 most recently loaded keys of this RECORD_SOURCE (latest changes)
    select PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_IDENTIFICATION
     where RECORD_SOURCE = 'MAXIMUS'
     group by PARTY_HKEY
     order by max(LOAD_DATETIME) desc, hkey
     limit 100
),
c1 as (  -- latest satellite row per sampled key
    select PARTY_HKEY as hkey,
           PASSPORTNUMBER:"BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW"::varchar as PASSPORTNUMBER
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_IDENTIFICATION
     where RECORD_SOURCE = 'MAXIMUS'
       and PARTY_HKEY in (select hkey from s1)
    qualify rank() over (partition by PARTY_HKEY order by LOAD_DATETIME desc) = 1
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select hkey, max(PASSPORTNUMBER) as PASSPORTNUMBER
      from (
        -- via stg_maximus__pd_prop_msdp_pv
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || ((nullif(trim(to_varchar("FOREIGN_KEY")), ''))) AS VARCHAR))), '')) as hkey,
               ("REC_REFRESH_AT"::timestamp_ntz) as ldts,
               to_varchar((nullif(trim(to_varchar("PASSPORT_NUMBER")), ''))) as PASSPORTNUMBER
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW
      )
     where hkey in (select hkey from s1) and ldts is not null
     group by hkey
),
r1 as (
    select 'PASSPORTNUMBER' as column_name, c.hkey, c.PASSPORTNUMBER as sat_value,
           max(iff(equal_null(c.PASSPORTNUMBER, e.PASSPORTNUMBER), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.PASSPORTNUMBER) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.PASSPORTNUMBER
),
s2 as (  -- the 100 most recently loaded keys of this RECORD_SOURCE (latest changes)
    select PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_IDENTIFICATION
     where RECORD_SOURCE = 'MAXIMUS'
     group by PARTY_HKEY
     order by max(LOAD_DATETIME) desc, hkey
     limit 100
),
c2 as (  -- latest satellite row per sampled key
    select PARTY_HKEY as hkey,
           AADHAARNUMBER:"BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW"::varchar as AADHAARNUMBER,
           CKYCNUMBER:"BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW"::varchar as CKYCNUMBER,
           GSTIN:"BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW"::varchar as GSTIN,
           PANNUMBER:"BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW"::varchar as PANNUMBER,
           PASSPORTNUMBER:"BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW"::varchar as PASSPORTNUMBER,
           VOTERIDNUMBER:"BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW"::varchar as VOTERIDNUMBER
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_IDENTIFICATION
     where RECORD_SOURCE = 'MAXIMUS'
       and PARTY_HKEY in (select hkey from s2)
    qualify rank() over (partition by PARTY_HKEY order by LOAD_DATETIME desc) = 1
),
e2 as (  -- expected value(s) at the latest RAW load timestamp per key
    select hkey, max(AADHAARNUMBER) as AADHAARNUMBER, max(CKYCNUMBER) as CKYCNUMBER, max(GSTIN) as GSTIN, max(PANNUMBER) as PANNUMBER, max(PASSPORTNUMBER) as PASSPORTNUMBER, max(VOTERIDNUMBER) as VOTERIDNUMBER
      from (
        -- via stg_maximus__pd_prop_sp_pv
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || ((nullif(trim(to_varchar("BAGIC_EMPLOYEE_CODE")), ''))) AS VARCHAR))), '')) as hkey,
